Subroutine Dividir(a As Integer, b As Integer, cociente As Integer By Reference, resto As Integer By Reference)
  cociente <- a Div b;
  resto <- a Mod b;
EndSubroutine

Algorithm Principal
  Define c, r As Integer;
  Dividir(17, 5, c, r);
  Write c, " ", r;
EndAlgorithm

Subroutine Incrementar(n As Integer By Reference)
  n <- n + 1;
EndSubroutine

Algorithm Principal
  Incrementar(5);
EndAlgorithm
